import { StandardEvents } from '@shopify/events';

const initApprovedProduct = (root) => {
  if (!root || root.dataset.approvedReady === 'true') return;
  root.dataset.approvedReady = 'true';

  const variantsNode = root.parentElement?.querySelector('[data-approved-variants]');
  let variants = [];
  try {
    variants = JSON.parse(variantsNode?.textContent || '[]');
  } catch {
    variants = [];
  }

  const form = root.querySelector('form[data-type="add-to-cart-form"]');
  const variantInput = form?.querySelector('input[name="id"]');
  const currentPrice = root.querySelector('[data-approved-current]');
  const comparePrice = root.querySelector('[data-approved-compare]');
  const discount = root.querySelector('[data-approved-discount]');
  const savings = root.querySelector('[data-approved-savings]');
  const addButton = root.querySelector('[data-approved-add]');
  const message = root.querySelector('[data-approved-form-message]');
  const quantityInput = root.querySelector('[data-approved-quantity] input');
  const hero = root.querySelector('[data-approved-hero]');
  const viewport = root.querySelector('[data-approved-gallery-viewport]');
  const track = root.querySelector('[data-approved-gallery-track]');
  const thumbsContainer = root.querySelector('.brunito-approved-product__thumbs');
  let thumbs = [...root.querySelectorAll('[data-approved-thumb]')];
  const counter = root.querySelector('[data-approved-gallery-counter]');
  const mediaNode = root.querySelector('[data-approved-gallery-media]');
  const galleryConfigNode = root.querySelector('[data-approved-gallery-config]');
  const lightbox = root.querySelector('[data-approved-gallery-lightbox]');
  const lightboxImage = lightbox?.querySelector('[data-approved-lightbox-image]');
  let allMedia = [];
  let galleryConfig = null;
  try {
    allMedia = JSON.parse(mediaNode?.textContent || '[]');
    galleryConfig = JSON.parse(galleryConfigNode?.textContent || 'null');
  } catch {
    allMedia = [];
    galleryConfig = null;
  }
  const mediaById = new Map(allMedia.map((media) => [String(media.id), media]));
  let galleryMedia = thumbs.map((thumb) => mediaById.get(String(thumb.dataset.mediaId))).filter(Boolean);
  if (!galleryMedia.length) galleryMedia = allMedia;
  const allSlides = [...root.querySelectorAll('[data-approved-gallery-slide]')];
  const slideById = new Map(allSlides.map((slide) => [String(slide.dataset.mediaId), slide]));
  let slides = allSlides.filter((slide) => !slide.hidden);
  const reorderSlides = () => {
    if (!track) return;
    galleryMedia.forEach((media) => {
      const slide = slideById.get(String(media.id));
      if (slide) track.append(slide);
    });
    slides = allSlides.filter((slide) => !slide.hidden);
  };
  reorderSlides();
  thumbs.forEach((thumb) => {
    thumb.dataset.mediaIndex = String(galleryMedia.findIndex((media) => String(media.id) === String(thumb.dataset.mediaId)));
  });
  const confirmation = root.parentElement?.querySelector('[data-brunito-cart-confirmation]');
  const confirmationImage = confirmation?.querySelector('[data-brunito-cart-confirmation-image]');
  const confirmationName = confirmation?.querySelector('[data-brunito-cart-confirmation-name]');
  const confirmationVariant = confirmation?.querySelector('[data-brunito-cart-confirmation-variant]');
  const confirmationPrice = confirmation?.querySelector('[data-brunito-cart-confirmation-price]');
  const confirmationQuantity = confirmation?.querySelector('[data-brunito-cart-confirmation-quantity]');
  const confirmationRelated = confirmation?.querySelector('[data-brunito-cart-confirmation-related]');
  let activeMedia = Math.max(0, thumbs.findIndex((thumb) => thumb.getAttribute('aria-current') === 'true'));
  let lastGalleryColor = null;
  const initialSlide = slides.find((slide) => String(slide.dataset.mediaId) === String(galleryMedia[activeMedia]?.id));
  if (viewport && initialSlide) viewport.scrollLeft = initialSlide.offsetLeft;

  const money = (value) => {
    const amount = Number(value || 0) / 100;
    const isLatamPhaseOne = root.dataset.latamPhaseOne === 'true';
    return new Intl.NumberFormat(document.documentElement.lang || 'es-ES', {
      style: 'currency',
      currency: window.Shopify?.currency?.active || 'EUR',
      currencyDisplay: isLatamPhaseOne ? 'code' : 'symbol',
    }).format(amount);
  };

  const prepareNeighborImages = () => {
    if (!galleryMedia.length) return;
    const neighborIndexes = new Set([activeMedia, activeMedia - 1, activeMedia + 1]);
    neighborIndexes.forEach((rawIndex) => {
      const index = (rawIndex + galleryMedia.length) % galleryMedia.length;
      const media = galleryMedia[index];
      const slide = slideById.get(String(media.id));
      const image = slide?.querySelector('[data-approved-slide-image]');
      if (!image) return;
      image.loading = 'eager';
      image.fetchPriority = index === activeMedia ? 'high' : 'auto';
    });
  };

  const updateActiveMedia = (index) => {
    if (!galleryMedia.length || !hero) return;
    activeMedia = (index + galleryMedia.length) % galleryMedia.length;
    const media = galleryMedia[activeMedia];
    hero.dataset.approvedMediaId = media.id;
    allSlides.forEach((slide) => {
      const active = String(slide.dataset.mediaId) === String(media.id);
      slide.classList.toggle('is-active', active);
      slide.setAttribute('aria-hidden', String(!active));
    });
    thumbs.forEach((item, itemIndex) => {
      const active = itemIndex === activeMedia;
      item.classList.toggle('is-active', active);
      item.setAttribute('aria-current', String(active));
    });
    if (counter) counter.textContent = `${activeMedia + 1} / ${galleryMedia.length}`;
    thumbs[activeMedia]?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    prepareNeighborImages();
  };

  const selectMedia = (index, behavior = 'smooth') => {
    if (!galleryMedia.length || !viewport) return;
    const nextIndex = (index + galleryMedia.length) % galleryMedia.length;
    const media = galleryMedia[nextIndex];
    const slide = slides.find((item) => String(item.dataset.mediaId) === String(media.id));
    if (!slide) return;
    viewport.scrollTo({ left: slide.offsetLeft, behavior });
  };

  const syncActiveSlideFromScroll = () => {
    if (!viewport || !slides.length) return;
    const viewportCenter = viewport.scrollLeft + viewport.clientWidth / 2;
    let nearestSlide = slides[0];
    let nearestDistance = Number.POSITIVE_INFINITY;
    slides.forEach((slide) => {
      const slideCenter = slide.offsetLeft + slide.clientWidth / 2;
      const distance = Math.abs(slideCenter - viewportCenter);
      if (distance < nearestDistance) {
        nearestDistance = distance;
        nearestSlide = slide;
      }
    });
    const nextIndex = galleryMedia.findIndex((media) => String(media.id) === String(nearestSlide.dataset.mediaId));
    if (nextIndex >= 0 && nextIndex !== activeMedia) updateActiveMedia(nextIndex);
  };

  let scrollFrame = null;
  viewport?.addEventListener('scroll', () => {
    if (scrollFrame) return;
    scrollFrame = requestAnimationFrame(() => {
      scrollFrame = null;
      syncActiveSlideFromScroll();
    });
  }, { passive: true });

  const renderThumbs = () => {
    if (!thumbsContainer) return;
    const fragment = document.createDocumentFragment();
    galleryMedia.forEach((media, index) => {
      const thumb = document.createElement('button');
      thumb.type = 'button';
      thumb.className = 'brunito-approved-product__thumb';
      thumb.dataset.approvedThumb = '';
      thumb.dataset.mediaId = media.id;
      thumb.dataset.mediaIndex = String(index);
      thumb.setAttribute('aria-label', `Imagen ${index + 1}`);
      thumb.setAttribute('aria-current', 'false');

      const image = document.createElement('img');
      image.src = media.thumbSrc || media.src;
      image.alt = media.alt || '';
      image.loading = 'lazy';
      image.decoding = 'async';
      image.width = 180;
      image.height = 180;
      thumb.append(image);
      fragment.append(thumb);
    });
    thumbsContainer.replaceChildren(fragment);
    thumbs = [...thumbsContainer.querySelectorAll('[data-approved-thumb]')];
  };

  const setGalleryMedia = (mediaIds, preferredMediaId) => {
    const nextMedia = mediaIds
      .map((mediaId) => allMedia.find((media) => String(media.id) === String(mediaId)))
      .filter(Boolean);
    if (!nextMedia.length) return false;

    galleryMedia = nextMedia;
    allSlides.forEach((slide) => {
      slide.hidden = !galleryMedia.some((media) => String(media.id) === String(slide.dataset.mediaId));
    });
    reorderSlides();
    renderThumbs();
    const preferredIndex = galleryMedia.findIndex((media) => String(media.id) === String(preferredMediaId));
    const nextIndex = preferredIndex >= 0 ? preferredIndex : 0;
    updateActiveMedia(nextIndex);
    selectMedia(nextIndex, 'auto');
    return true;
  };

  const scrollToGallery = () => {
    const gallery = root.querySelector('[data-approved-gallery]');
    if (!gallery) return;
    const header = document.querySelector('#header-group, header-group, header-component');
    const headerHeight = header?.getBoundingClientRect().height || 0;
    const targetTop = Math.max(0, gallery.getBoundingClientRect().top + window.scrollY - headerHeight - 12);
    window.scrollTo({ top: targetTop, behavior: 'smooth' });
  };

  const openLightbox = (mediaId) => {
    const media = mediaById.get(String(mediaId));
    if (!lightbox || !lightboxImage || !media) return;
    lightboxImage.src = media.fullSrc || media.src || '';
    lightboxImage.removeAttribute('srcset');
    lightboxImage.sizes = '100vw';
    lightboxImage.alt = media.alt || '';
    lightbox.showModal();
  };

  const closeLightbox = () => {
    if (lightbox?.open) lightbox.close();
  };

  thumbsContainer?.addEventListener('click', (event) => {
    const thumb = event.target.closest('[data-approved-thumb]');
    if (!thumb || !thumbsContainer.contains(thumb)) return;
    selectMedia(Number(thumb.dataset.mediaIndex));
  });
  root.querySelector('[data-approved-gallery-prev]')?.addEventListener('click', () => selectMedia(activeMedia - 1));
  root.querySelector('[data-approved-gallery-next]')?.addEventListener('click', () => selectMedia(activeMedia + 1));

  let tapStart = null;
  viewport?.addEventListener('pointerdown', (event) => {
    if (!event.isPrimary || event.target.closest('button')) return;
    tapStart = { x: event.clientX, y: event.clientY, pointerId: event.pointerId };
  }, { passive: true });
  viewport?.addEventListener('pointerup', (event) => {
    if (!tapStart || event.pointerId !== tapStart.pointerId) return;
    const distance = Math.hypot(event.clientX - tapStart.x, event.clientY - tapStart.y);
    const target = event.target instanceof Element ? event.target : null;
    const mediaId = target?.closest('[data-approved-gallery-slide]')?.dataset.mediaId;
    tapStart = null;
    if (distance <= 10 && mediaId) window.setTimeout(() => openLightbox(mediaId), 0);
  }, { passive: true });
  viewport?.addEventListener('pointercancel', () => { tapStart = null; }, { passive: true });

  lightbox?.querySelector('[data-approved-lightbox-close]')?.addEventListener('click', closeLightbox);
  lightbox?.addEventListener('click', (event) => {
    if (event.target === lightbox) closeLightbox();
  });

  const findVariant = () => {
    const selected = [...root.querySelectorAll('[data-approved-option-index]')].map((fieldset) => {
      const choice = fieldset.querySelector('[data-approved-option-value].is-selected');
      return choice?.dataset.approvedOptionValue || choice?.textContent?.trim() || null;
    });
    return variants.find((variant) => selected.every((value, index) => !value || variant.options?.[index] === value)) || null;
  };

  const populateConfirmationRecommendations = () => {
    if (!confirmationRelated) return;
    const suggestionScope = root.closest('main') || document;
    const sourceCards = [...suggestionScope.querySelectorAll('.brunito-product-suggestions__card')].slice(0, 3);
    confirmationRelated.replaceChildren();

    sourceCards.forEach((sourceCard) => {
      const sourceLink = sourceCard.querySelector('a');
      if (!sourceLink) return;

      const card = sourceLink.cloneNode(true);
      card.className = 'brunito-cart-confirmation__related-card';
      card.querySelectorAll('[id]').forEach((element) => element.removeAttribute('id'));
      card.querySelector('img')?.setAttribute('loading', 'lazy');

      if (sourceCard.querySelector('s')) {
        const badge = document.createElement('span');
        badge.className = 'brunito-cart-confirmation__related-offer';
        badge.textContent = 'Oferta';
        card.prepend(badge);
      }

      const add = document.createElement('span');
      add.className = 'brunito-cart-confirmation__related-add';
      add.textContent = '+';
      add.setAttribute('aria-hidden', 'true');
      card.append(add);
      confirmationRelated.append(card);
    });

    const relatedSection = confirmationRelated.closest('.brunito-cart-confirmation__related');
    if (relatedSection) relatedSection.hidden = sourceCards.length === 0;
  };

  const openCartConfirmation = (variant, quantity) => {
    if (!confirmation || !variant) return;
    const cartDrawer = document.querySelector('theme-drawer#cart-drawer');
    if (cartDrawer?.isOpen) cartDrawer.close();

    const activeSlideImage = slides.find((slide) => slide.classList.contains('is-active'))?.querySelector('[data-approved-slide-image]');
    if (confirmationImage && activeSlideImage) {
      confirmationImage.src = activeSlideImage.currentSrc || activeSlideImage.src;
      confirmationImage.alt = activeSlideImage.alt || root.querySelector('h1')?.textContent?.trim() || 'Producto añadido';
    }
    if (confirmationName) confirmationName.textContent = root.querySelector('h1')?.textContent?.trim() || 'Producto añadido';
    if (confirmationVariant) confirmationVariant.textContent = variant.title || variant.options?.filter(Boolean).join(' · ') || '';
    if (confirmationPrice) confirmationPrice.textContent = money(variant.price);
    if (confirmationQuantity) {
      confirmationQuantity.textContent = quantity > 1 ? `Cantidad: ${quantity}` : '';
      confirmationQuantity.hidden = quantity <= 1;
    }
    populateConfirmationRecommendations();

    if (!confirmation.open) confirmation.showModal();
    confirmation.querySelector('[data-brunito-cart-confirmation-close]')?.focus();
  };

  const updateVariant = (variant) => {
    const variantId = variant?.id ? String(variant.id) : '';
    if (variantInput) {
      variantInput.value = variantId;
      variantInput.setAttribute('value', variantId);
      variantInput.dataset.approvedVariantId = variantId;
    }

    const formVariantId = form ? String(new FormData(form).get('id') || '') : '';
    const canSubmit = Boolean(variant?.available && variantId && formVariantId === variantId);

    if (addButton) addButton.disabled = !canSubmit;

    const sticky = root.parentElement?.querySelector('sticky-add-to-cart');
    const stickyButton = sticky?.querySelector('[ref="addToCartButton"]');
    if (stickyButton) stickyButton.disabled = !canSubmit;

    if (!variant) return;
    const tools = root.querySelector('[data-brunito-product-tools]');
    if (tools) tools.dataset.productVariantId = variant.id;
    if (currentPrice) currentPrice.textContent = money(variant.price);

    const hasCompare = Number(variant.compare_at_price) > Number(variant.price);
    if (comparePrice) {
      comparePrice.textContent = hasCompare ? money(variant.compare_at_price) : '';
      comparePrice.hidden = !hasCompare;
    }
    const amountSaved = Math.max(0, Number(variant.compare_at_price || 0) - Number(variant.price || 0));
    const discountPercent = hasCompare ? Math.round((amountSaved / Number(variant.compare_at_price)) * 100) : 0;
    if (discount) {
      discount.textContent = discountPercent ? `OFERTA · -${discountPercent}%` : '';
      discount.hidden = !discountPercent;
    }
    if (savings) {
      savings.textContent = amountSaved ? `Ahorras ${money(amountSaved)}` : '';
      savings.hidden = !amountSaved;
    }
    if (addButton) addButton.textContent = variant.available ? 'Añadir al carrito' : 'Agotado';
    if (sticky) {
      sticky.dataset.currentVariantId = String(variant.id);
      sticky.dataset.variantAvailable = String(Boolean(variant.available));
      const stickyVariant = sticky.querySelector('.sticky-add-to-cart__variant');
      if (stickyVariant) stickyVariant.textContent = variant.title || '';
      const stickyPrice = sticky.querySelector('[data-testid="sticky-price-display"]');
      if (stickyPrice) {
        const stickyCompare = Number(variant.compare_at_price) > Number(variant.price) ? `<s>${money(variant.compare_at_price)}</s>` : '';
        stickyPrice.innerHTML = `${stickyCompare}<strong>${money(variant.price)}</strong>`;
      }
      if (stickyButton) {
        const stickyText = stickyButton.querySelector('.add-to-cart-text__content > span');
        if (stickyText) stickyText.textContent = variant.available ? 'Añadir al carrito' : 'Agotado';
      }
    }
    const selectedColor = String(variant.options?.[galleryConfig?.colorOptionIndex] || '').toLowerCase();
    const configuredMediaIds = galleryConfig?.groups?.[selectedColor];
    const colorChanged = Boolean(galleryConfig && selectedColor && lastGalleryColor !== null && selectedColor !== lastGalleryColor);
    if (Array.isArray(configuredMediaIds) && configuredMediaIds.length) {
      setGalleryMedia(configuredMediaIds, configuredMediaIds[0]);
      if (colorChanged) window.requestAnimationFrame(scrollToGallery);
      lastGalleryColor = selectedColor;
    } else {
      const mediaId = variant.featured_media?.id || variant.featured_image?.id;
      if (mediaId) {
        const mediaIndex = galleryMedia.findIndex((media) => String(media.id) === String(mediaId));
        if (mediaIndex >= 0) selectMedia(mediaIndex);
      }
      if (galleryConfig) lastGalleryColor = selectedColor || lastGalleryColor;
    }
  };

  root.querySelectorAll('[data-approved-option-value]').forEach((choice) => {
    choice.addEventListener('click', () => {
      const fieldset = choice.closest('[data-approved-option-index]');
      fieldset?.querySelectorAll('[data-approved-option-value]').forEach((item) => {
        const active = item === choice;
        item.classList.toggle('is-selected', active);
        item.setAttribute('aria-pressed', String(active));
      });
      const selectedLabel = fieldset?.querySelector('[data-approved-selected-label]');
      if (selectedLabel) selectedLabel.textContent = choice.textContent.trim();
      updateVariant(findVariant());
    });
  });

  root.querySelector('[data-approved-quantity-minus]')?.addEventListener('click', () => {
    if (!quantityInput) return;
    quantityInput.value = String(Math.max(Number(quantityInput.min || 1), Number(quantityInput.value || 1) - 1));
  });
  root.querySelector('[data-approved-quantity-plus]')?.addEventListener('click', () => {
    if (!quantityInput) return;
    quantityInput.value = String(Math.max(Number(quantityInput.min || 1), Number(quantityInput.value || 1) + 1));
  });

  form?.addEventListener('submit', () => {
    if (message) message.textContent = '';
  });

  document.addEventListener(StandardEvents.cartLinesUpdate, (event) => {
    if (event.action !== 'add' || event.context !== 'product' || !event.promise) return;
    if (!(event.target instanceof Element) || !root.contains(event.target)) return;

    event.promise
      .then(({ detail }) => {
        if (detail?.didError) return;
        const quantity = Math.max(1, Number(form?.querySelector('[name="quantity"]')?.value || 1));
        requestAnimationFrame(() => openCartConfirmation(findVariant(), quantity));
      })
      .catch(() => {});
  });

  confirmation?.querySelectorAll('[data-brunito-cart-confirmation-close]').forEach((control) => {
    control.addEventListener('click', () => confirmation.close());
  });
  confirmation?.addEventListener('click', (event) => {
    if (event.target === confirmation) confirmation.close();
  });
  confirmation?.addEventListener('close', () => addButton?.focus({ preventScroll: true }));

  updateVariant(findVariant());
  prepareNeighborImages();
};

document.querySelectorAll('[data-section-id].brunito-approved-product').forEach(initApprovedProduct);
document.addEventListener('shopify:section:load', (event) => initApprovedProduct(event.target.querySelector?.('.brunito-approved-product')));
